/** Translate only reviewed strings; never guess, delete a condition, or alter source objects. */
export function englishText(text: string): string {
  const exact = ENGLISH[text] ?? CATALOG[text];
  if (exact !== undefined) return exact;
  if (text.startsWith('Re: ')) return 'Re: ' + englishText(text.slice(4));
  if (text.includes(' · ')) return text.split(' · ').map(englishText).join(' · ');
  return text;
}
